<script setup lang="ts">
import { onMounted, reactive, ref } from "vue";import type { Pige360SessionClient } from "@pige360/auth";type Row=Record<string,any>;const props=defineProps<{api:Pige360SessionClient}>();const emit=defineEmits<{error:[message:string]}>();const events=ref<Row[]>([]),trips=ref<Row[]>([]),selected=ref<Row|null>(null),notice=ref("");const eventForm=reactive({event_type:"meeting",name:"",starts_at:"",ends_at:"",location:"",capacity:50,registration_fee:"0.00",authorization_required:false});const tripForm=reactive({event_id:"",name:"",destination:"",starts_at:"",ends_at:""});function msg(e:unknown){return e instanceof Error?e.message:"Erro inesperado"}async function request<T=Row>(p:string,i:RequestInit={}){return props.api.request<T>(p,i)}async function post<T=Row>(p:string,b:any){return request<T>(p,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(b)})}async function load(){try{events.value=(await request<Row>("/events")).items||[];trips.value=(await request<Row>("/trips")).items||[]}catch(e){emit("error",msg(e))}}async function createEvent(){try{await post("/events",eventForm);notice.value="Evento criado em rascunho.";await load()}catch(e){emit("error",msg(e))}}async function publishEvent(e:Row){try{await post(`/events/${e.id}/publish`,{});await load()}catch(x){emit("error",msg(x))}}async function detail(e:Row){try{selected.value=await request<Row>(`/events/${e.id}`)}catch(x){emit("error",msg(x))}}async function createTrip(){try{await post("/trips",{...tripForm,event_id:tripForm.event_id||null,itinerary:[],vehicles:[],emergency:{}});notice.value="Viagem criada.";await load()}catch(e){emit("error",msg(e))}}async function publishTrip(t:Row){try{await post(`/trips/${t.id}/publish`,{});await load()}catch(e){emit("error",msg(e))}}onMounted(load);
</script><template><div v-if="notice" class="flash success">{{notice}}</div><section class="grid-2 forms"><form class="panel" @submit.prevent="createEvent"><h2>Novo evento</h2><div class="cols"><label>Tipo<input v-model="eventForm.event_type" required></label><label>Capacidade<input v-model.number="eventForm.capacity" type="number" min="1"></label></div><label>Nome<input v-model="eventForm.name" required></label><label>Local<input v-model="eventForm.location"></label><div class="cols"><label>Início<input v-model="eventForm.starts_at" type="datetime-local" required></label><label>Fim<input v-model="eventForm.ends_at" type="datetime-local" required></label></div><div class="cols"><label>Taxa<input v-model="eventForm.registration_fee" type="number" step="0.01"></label><label class="inline"><input v-model="eventForm.authorization_required" type="checkbox"> Exigir autorização</label></div><button class="primary">Criar evento</button></form><form class="panel" @submit.prevent="createTrip"><h2>Nova viagem</h2><label>Evento<select v-model="tripForm.event_id"><option value="">Sem evento</option><option v-for="e in events" :value="e.id">{{e.name}}</option></select></label><label>Nome<input v-model="tripForm.name" required></label><label>Destino<input v-model="tripForm.destination" required></label><div class="cols"><label>Saída<input v-model="tripForm.starts_at" type="datetime-local" required></label><label>Retorno<input v-model="tripForm.ends_at" type="datetime-local" required></label></div><button class="primary">Criar viagem</button></form></section><section class="grid-2"><div class="panel"><div class="panel-title"><h2>Eventos</h2><span>{{events.length}}</span></div><table><thead><tr><th>Evento</th><th>Data</th><th>Vagas</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="e in events" :key="e.id"><td><button class="link" @click="detail(e)">{{e.name}}</button></td><td>{{e.starts_at}}</td><td>{{e.capacity||'livre'}}</td><td>{{e.state}}</td><td><button v-if="e.state==='draft'" class="small" @click="publishEvent(e)">Publicar</button></td></tr></tbody></table></div><div class="panel"><div class="panel-title"><h2>Viagens</h2><span>{{trips.length}}</span></div><table><thead><tr><th>Viagem</th><th>Destino</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="t in trips" :key="t.id"><td>{{t.name}}</td><td>{{t.destination}}</td><td>{{t.state}}</td><td><button v-if="t.state==='draft'" class="small" @click="publishTrip(t)">Publicar</button></td></tr></tbody></table></div></section><section v-if="selected" class="panel"><div class="panel-title"><h2>{{selected.name}}</h2><span>{{selected.registrations?.length||0}} inscritos</span></div><table><thead><tr><th>Participante</th><th>Estado</th><th>Taxa</th><th>Check-in</th><th>Check-out</th></tr></thead><tbody><tr v-for="r in selected.registrations" :key="r.id"><td>{{r.person_name}}</td><td>{{r.state}}</td><td>R$ {{Number(r.fee_amount||0).toFixed(2)}}</td><td>{{r.checked_in_at||'—'}}</td><td>{{r.checked_out_at||'—'}}</td></tr></tbody></table></section></template>
